     "**一名堪用的輔助**，能減少彈幕關卡的重試次數（續航、功能性，或強力的能量供給）。",
     "足夠的前期神器或轉換解鎖進度，讓[神器與能量](#guides__artifacts-energy)這套系統真的能運作。",
     "帳號能完整綁定到 EROLABS，而不必共用一個你即將丟棄的免洗 Google 登入。"
