     "領取信箱（碎星、召喚券、符合資格的封測回饋）。",
     "套用[抽卡與召喚](#guides__gacha-summon)裡的花費規則。",
     "開始在主力身上執行每日羈絆勾選（[羈絆檢查清單](#tools__bond-checklist)）。",
     "睡前掛上掛機路線（[戰鬥與掛機](#guides__combat-idle)）。",
     "把星球港推得夠遠，讓劇情免費六星的養成能餵給同一名主力。"
