    "text": "戰力不只來自等級與抽卡稀有度。精神面的[姬絆](#guides__hime-bonds)與肉體面的[伴侶](#guides__cumpanions)會提升官方文案所說、可轉化為神器的情感能量。請把戰鬥想成 **成果驗證**，把羈絆想成 **電池**。"
