     "跑完[新手入門玩法](#guides__how-to-play)，讓選單與循環有意義。",
     "領取[上線獎勵](#events__launch-rewards)信件（碎星／封測回饋）——這些不是兌換碼；公開序號請見[可用兌換碼](#codes__active)。",
     "在大量投資之前，先決定要不要[洗初始帳號](#guides__reroll)。",
     "透過[抽卡與召喚](#guides__gacha-summon)鎖定一個新手招募目標。",
