    "text": "姬絆與伴侶不是抽卡，但它們爭奪的是同一份每週注意力預算。一個你永遠不會送禮的角色，既不該拿到召喚券，**也** 不該拿到突破材料。反過來說，一個你完整培養羈絆的中階愛角，可以贏過一個被冷落的 SSR，因為能量轉換會餵養神器。因此，抽取優先度也包含 **這個月你打算培養誰的羈絆**，而不只是誰出現在機率提升上。"
