     "在第一套核心還打不過當前星球港之前，就去抽重複角色。",
     "在沒有活動的空窗週買體力禮包。",
     "把已經課金的帳號拿去洗初始——洗初始是給尚未綁定的全新開局用的（[洗初始帳號](#guides__reroll)）。"
