    "text": "如果你還有第一天的信件沒領——約 **5000** 碎星、封測 **200%** 星鑽回饋、登入抽取、嘉年華獎勵——請先把[上線獎勵](#events__launch-rewards)處理完，再去最佳化某個隨機的支線任務板。"
