     "**活動商店** — 把剩餘代幣花在符合[養成進度](#builds__progression)的主力專屬部件與限定模組上，而不是重複的填充碎片。",
     "**每日作業系統** — 從[新手第一週規劃](#guides__beginner-week)畢業到[每日行程](#guides__daily-routine)，這樣當華麗的任務板消失後，羈絆、掛機與一個戰鬥時段仍然照常進行。",
